package cms;
import java.util.*;
import java.io.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import dao.*;
import dto.*;
import ai.consultation.*;
import ai.session.*;
import ai.dto.*;
import static ai.ConsultationBehaviorTest.*;
public class CmsBehaviorTest {
    static int passed;
    static void pass(String name){passed++;System.out.println("PASS "+name);}
    public static void main(String[] args)throws Exception{
        FakeDatabase db=new FakeDatabase();db.install();SettingsDAO store=new SettingsDAO();
        Map<String,String> updates=new LinkedHashMap<>();updates.put("cms.hero.title","Tiêu đề mới");updates.put("cms.business.phone","0912345678");
        check(store.saveVersioned(updates,101,"content"),"Publish failed");check(SiteContent.load().get("hero.title").equals("Tiêu đề mới"),"Refresh lost content");pass("transactional title save persists across fresh reads");
        db.settings.put("ai_provider_gemini_key","DO_NOT_EXPOSE_SYNTHETIC_KEY");Map<String,String> publicValues=SiteContent.load();check(!publicValues.toString().contains("DO_NOT_EXPOSE"),"Secret reached public data");pass("public snapshot excludes operational secrets");
        Map<String,String> before=new LinkedHashMap<>(db.settings);int versions=db.revisions.size();db.failKey="cms.business.email";updates.clear();updates.put("cms.hero.title","Would roll back");updates.put("cms.business.email","new@example.invalid");check(!store.saveVersioned(updates,101,"content")&&db.settings.equals(before)&&db.revisions.size()==versions,"Partial transaction persisted");db.failKey=null;pass("failed batch rolls back all values and revision");
        check(store.rollbackLatest(1,101,"content")&&!db.settings.containsKey("cms.hero.title"),"Rollback did not restore missing setting");pass("latest revision restores prior default");
        check(!store.rollbackLatest(1,101,"content"),"Stale revision overwritten current content");pass("obsolete rollback is rejected");
        check(store.rollbackLatest(2,101,"content")&&"Tiêu đề mới".equals(SiteContent.load().get("hero.title")),"Rollback could not restore deleted setting");pass("rollback of a rollback recreates previously absent settings atomically");
        for(String url:new String[]{"javascript:alert(1)","//attacker.invalid","/../secret","https://user@attacker.invalid","/admin/users","/media?id=../../"}){boolean bad=false;try{SiteContent.safeUrl(url,false);}catch(IllegalArgumentException expected){bad=true;}check(bad,"Unsafe URL "+url);}pass("unsafe URLs rejected");
        SiteContent.safeUrl("#packages",false);SiteContent.safeUrl("/assets/images/Hero1.png",true);pass("approved public links and images accepted");
        Map<String,String> v=SiteContent.defaults();v.put("business.promotionTitle","Ưu đãi minh họa");v.put("business.promotionActive","true");v.put("business.promotionEnd","2000-01-01");check(!SiteContent.promotionVisible(v),"Expired promotion published");v.put("business.promotionEnd","");check(SiteContent.promotionVisible(v),"Active promotion disappeared");v.put("business.promotionActive","false");check(!SiteContent.promotionVisible(v),"Inactive promotion displayed");pass("promotion dates and visibility enforced");
        PackageDTO pack=new PackageDAO().getById(3);int id=pack.getId();pack.setPrice(225000);pack.setSpeedMbps(700);pack.setStandardInstallationFee(350000);pack.setDisplayOrder(5);pack.setActive(true);
        check(new PackageDAO().saveManaged(pack,false,101),"Package save failed");ProductCatalog catalog=SiteContent.publicCatalog();check(catalog.byId(id).price==225000&&catalog.byId(id).speed==700&&catalog.byId(id).standardInstallationFee==350000,"UI/chat catalog mismatch");pass("package updates preserve ID and propagate to authoritative chat catalog");
        pack.setActive(false);check(new PackageDAO().saveManaged(pack,false,101)&&SiteContent.publicCatalog().byId(id)==null,"Inactive package remains public");pass("inactive package disappears from public and chat catalog");
        pack.setActive(true);pack.setInstallationFeeInherited(true);check(new PackageDAO().saveManaged(pack,false,101),"Inheritance save failed");db.settings.put("cms.business.standardFee","360000");check(SiteContent.publicCatalog().byId(id).standardInstallationFee==360000&&!db.settings.containsKey("cms.package."+id+".fee"),"Global fee inheritance broken");pass("global installation fee applies after managed package price changes");
        List<PackageDTO> rows=DemoData.packages();v=SiteContent.defaults();v.put("business.phone","0912345678");v.put("business.zalo","https://zalo.me/0912345678");v.put("business.standardFee","350000");v.put("business.meshF1Fee","555000");v.put("business.meshF1Monthly","15000");for(PackageDTO p:rows)p.setStandardInstallationFee(350000);catalog=new ProductCatalog(rows,v);
        ChatResponse answer=new ConsultationEngine().chat("Phí lắp mạng bao nhiêu?",new ChatSessionData("cms-fee"),catalog,null,null,new ChatOptions(0.3,1200));check(answer.getContent().contains("350.000"),answer.getContent());pass("chat uses approved installation fee");
        rows.get(0).setStandardInstallationFee(250000);rows.get(2).setStandardInstallationFee(400000);catalog=new ProductCatalog(rows,v);answer=ConsultationPolicy.installationFee("Phí lắp mạng bao nhiêu?",new CustomerRequirements(),catalog);check(answer.getContent().contains("350.000")&&!answer.getContent().contains("250.000"),answer.getContent());answer=ConsultationPolicy.installationFee("So sánh phí lắp gói 195K và 220K",new CustomerRequirements(),catalog);check(answer.getContent().contains("250.000")&&answer.getContent().contains("400.000")&&answer.getContent().contains("195.000đ/tháng")&&answer.getContent().contains("220.000đ/tháng"),answer.getContent());pass("standard and individual installation fees remain distinct from monthly prices");
        answer=ConsultationPolicy.known("Mesh F1 phí bao nhiêu?",new CustomerRequirements(),catalog);check(answer.getContent().contains("555.000")&&answer.getContent().contains("15.000"),answer.getContent());pass("chat uses approved Mesh data");
        answer=ConsultationPolicy.known("Tôi muốn nói chuyện với người thật",new CustomerRequirements(),catalog);check(answer.getContent().contains("0912 345 678")&&!answer.getContent().contains("0932"),answer.getContent());pass("chat uses approved contact");
        v.put("business.meshF1Fee","700000");v.put("business.meshF2Fee","800000");v.put("business.meshF2Monthly","27000");String fixed=ConsultationPolicy.facts("220.000đ/tháng; 500.000 VNĐ; 700.000 VNĐ; 20.000đ/tháng",v);check(fixed.equals("220.000đ/tháng; 700.000 VNĐ; 800.000 VNĐ; 27.000đ/tháng"),fixed);pass("Mesh configuration cannot alter package prices or cascade replacements");
        db.customer.put("id",7);db.customer.put("full_name","Khách giả");db.customer.put("phone","0912345678");db.customer.put("package_interest","Gói 220K / ID 3");db.customer.put("status","Mới");CmsSecurityTest.Exchange edit=new CmsSecurityTest.Exchange("/admin/customers",CmsSecurityTest.user("admin"));edit.method="POST";edit.params.put("action","update");edit.params.put("id","7");edit.params.put("fullName","Khách minh họa mới");edit.params.put("phone","0912345678");edit.params.put("status","Đã liên hệ");new controller.AdminCustomerServlet().service(edit.request,edit.response);check(edit.status==302&&"Gói 220K / ID 3".equals(db.customer.get("package_interest"))&&"Đã liên hệ".equals(db.customer.get("status")),"Editing lost selected package or status");pass("registration edit preserves selected package and existing status values");
        int writes=db.writes;edit.params.put("status","Invented status");new controller.AdminCustomerServlet().service(edit.request,edit.response);check(edit.status==400&&db.writes==writes,"Invalid registration status persisted");pass("invalid registration status cannot write");
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(20,10,BufferedImage.TYPE_INT_RGB),"png",bytes);MediaStore.Image image=MediaStore.validate(new ByteArrayInputStream(bytes.toByteArray()));check(image.width==20&&image.height==10&&image.type.equals("image/png"),"Valid image rejected");pass("image decoded and sanitized");
        String mediaUrl=new MediaStore().save(image,101);check(db.media.size()==1&&java.util.Arrays.equals(image.bytes,(byte[])db.media.values().iterator().next().get("content")),"Durable media bytes not stored");pass("validated media is persisted by JDBC with UUID reference");
        boolean bad=false;try{MediaStore.validate(new ByteArrayInputStream("<script>not an image</script>".getBytes("UTF-8")));}catch(IOException expected){bad=true;}check(bad,"Spoofed image accepted");pass("image spoof rejected by content");
        bad=false;try{MediaStore.validate(new ByteArrayInputStream(new byte[2097153]));}catch(IOException expected){bad=true;}check(bad,"Oversized image accepted");pass("image size bound enforced");
        updates.clear();updates.put("ai_system_prompt","Prompt có phiên bản");updates.put("ai_provider_gemini_key","ANOTHER_SYNTHETIC_SECRET");check(store.saveVersioned(updates,101,"prompt"),"Prompt version failed");Map<String,Object> revision=db.revisions.get(db.revisions.size()-1);check(!revision.toString().contains("ANOTHER_SYNTHETIC_SECRET"),"Secret in revision");pass("prompt history never contains API key");
        System.out.println("CmsBehaviorTest: "+passed+" passed");
    }
}
